/** Myers-Diff für Zeilen sowie begrenzte Inline-Word-Diffs. */
import type { DiffHunk, DiffLine, InlineSegment } from "./types.ts";

type EditOp = "keep" | "insert" | "delete";

const MAX_LINES = 10_000;
// Myers ist O((N+M)*D) mit D = Edit-Distanz, nicht mit der Dateigröße selbst
// teuer — bei kleinen, lokalisierten Änderungen ist D klein, auch in langen
// Dateien. Die alten Werte (50_000 Bytes / 4_000 Zeilen) lagen unter der
// Größe gewöhnlicher Quelldateien dieses Repos (z. B. tool-renderers.ts,
// index.ts, tests/suites/runtime/aurora-ui.mjs) und ließen den Fallback
// dadurch bei praktisch jeder Bearbeitung dieser Dateien greifen: Statt
// eines echten Diffs zeigte die Ansicht "ganze Datei gelöscht + neu
// eingefügt". Die neuen Grenzwerte decken die realen Dateigrößen dieses
// Repos mit deutlichem Puffer ab und bleiben trotzdem klein genug, um ein
// pathologisches Worst-Case (komplett verschiedene Dateien) nicht spürbar
// zu verlangsamen.
const MAX_BYTES = 500_000;
const MAX_MYERS_LENGTH = 20_000;
const MAX_INLINE_TOKENS = 512;
const MAX_INLINE_MATRIX_CELLS = 65_536;

export function computeLineDiff(
  oldLines: string[],
  newLines: string[],
): EditOp[] {
  const size = oldLines.join("\n").length + newLines.join("\n").length;
  if (
    oldLines.length > MAX_LINES ||
    newLines.length > MAX_LINES ||
    oldLines.length + newLines.length > MAX_MYERS_LENGTH ||
    size > MAX_BYTES
  ) {
    return [
      ...oldLines.map(() => "delete" as const),
      ...newLines.map(() => "insert" as const),
    ];
  }
  return myers(oldLines, newLines);
}

function myers(a: string[], b: string[]): EditOp[] {
  const max = a.length + b.length;
  const trace: Array<Map<number, number>> = [];
  const v = new Map<number, number>([[1, 0]]);

  for (let d = 0; d <= max; d++) {
    // Snapshot des vorherigen D-Schritts für die Rückwärtsrekonstruktion.
    trace.push(new Map(v));
    for (let k = -d; k <= d; k += 2) {
      const down =
        k === -d || (k !== d && (v.get(k - 1) ?? -1) < (v.get(k + 1) ?? -1));
      let x = down ? (v.get(k + 1) ?? 0) : (v.get(k - 1) ?? 0) + 1;
      let y = x - k;
      while (x < a.length && y < b.length && a[x] === b[y]) {
        x++;
        y++;
      }
      v.set(k, x);
      if (x >= a.length && y >= b.length) return reconstruct(a, b, trace);
    }
  }
  return [...a.map(() => "delete" as const), ...b.map(() => "insert" as const)];
}

function reconstruct(
  a: string[],
  b: string[],
  trace: Array<Map<number, number>>,
): EditOp[] {
  const reversed: EditOp[] = [];
  let x = a.length;
  let y = b.length;
  for (let d = trace.length - 1; d > 0; d--) {
    const v = trace[d]!;
    const k = x - y;
    const down =
      k === -d || (k !== d && (v.get(k - 1) ?? -1) < (v.get(k + 1) ?? -1));
    const previousK = down ? k + 1 : k - 1;
    const previousX = v.get(previousK) ?? 0;
    const previousY = previousX - previousK;
    while (x > previousX && y > previousY) {
      reversed.push("keep");
      x--;
      y--;
    }
    reversed.push(down ? "insert" : "delete");
    if (down) y--;
    else x--;
  }
  while (x > 0 && y > 0) {
    reversed.push("keep");
    x--;
    y--;
  }
  while (x-- > 0) reversed.push("delete");
  while (y-- > 0) reversed.push("insert");
  return reversed.reverse();
}

interface ScriptStep {
  op: EditOp;
  oldLine?: number;
  newLine?: number;
  text: string;
}

/** Konvertiert ein Edit-Script in getrennte Unified-Diff-Hunks. */
export function scriptToHunks(
  oldLines: string[],
  newLines: string[],
  script: EditOp[],
  contextLines = 3,
): DiffHunk[] {
  const steps = buildSteps(oldLines, newLines, script);
  const changed = steps.flatMap((step, index) =>
    step.op === "keep" ? [] : [index],
  );
  if (changed.length === 0) return [];

  const ranges: Array<[number, number]> = [];
  let first = changed[0]!;
  let last = first;
  for (const index of changed.slice(1)) {
    // Context überlappt nur, wenn zwischen den Änderungen höchstens 2*context Zeilen liegen.
    if (index - last <= contextLines * 2 + 1) {
      last = index;
    } else {
      ranges.push([
        Math.max(0, first - contextLines),
        Math.min(steps.length - 1, last + contextLines),
      ]);
      first = index;
      last = index;
    }
  }
  ranges.push([
    Math.max(0, first - contextLines),
    Math.min(steps.length - 1, last + contextLines),
  ]);

  return ranges.map(([start, end]) => {
    const selected = steps.slice(start, end + 1);
    const lines: DiffLine[] = selected.map((step) => {
      if (step.op === "keep") {
        return {
          kind: "context",
          oldLine: step.oldLine,
          newLine: step.newLine,
          text: step.text,
        };
      }
      if (step.op === "delete") {
        return { kind: "removed", oldLine: step.oldLine, text: step.text };
      }
      return { kind: "added", newLine: step.newLine, text: step.text };
    });
    applyInlineHighlights(lines);
    return {
      oldStart:
        selected.find((step) => step.oldLine !== undefined)?.oldLine ?? 0,
      oldCount: lines.filter((line) => line.kind !== "added").length,
      newStart:
        selected.find((step) => step.newLine !== undefined)?.newLine ?? 0,
      newCount: lines.filter((line) => line.kind !== "removed").length,
      lines,
    };
  });
}

function buildSteps(
  oldLines: string[],
  newLines: string[],
  script: EditOp[],
): ScriptStep[] {
  const steps: ScriptStep[] = [];
  let oldIndex = 0;
  let newIndex = 0;
  for (const op of script) {
    if (op === "keep") {
      steps.push({
        op,
        oldLine: oldIndex + 1,
        newLine: newIndex + 1,
        text: oldLines[oldIndex] ?? "",
      });
      oldIndex++;
      newIndex++;
    } else if (op === "delete") {
      steps.push({ op, oldLine: oldIndex + 1, text: oldLines[oldIndex] ?? "" });
      oldIndex++;
    } else {
      steps.push({ op, newLine: newIndex + 1, text: newLines[newIndex] ?? "" });
      newIndex++;
    }
  }
  return steps;
}

/** Berechnet Word-Level-Diffs, ohne unbeschränkt quadratischen Speicher zu verwenden. */
export function computeWordDiff(
  oldText: string,
  newText: string,
): InlineSegment[] {
  if (oldText === newText) return [{ type: "equal", text: oldText }];
  if (!oldText) return [{ type: "added", text: newText }];
  if (!newText) return [{ type: "removed", text: oldText }];

  const oldTokens = tokenize(oldText);
  const newTokens = tokenize(newText);
  if (
    oldTokens.length + newTokens.length > MAX_INLINE_TOKENS ||
    oldTokens.length * newTokens.length > MAX_INLINE_MATRIX_CELLS
  ) {
    // Sicherer Fallback: Zeilenfarbe bleibt sichtbar, nur kein Wort-Level-Highlight.
    return [];
  }

  const matches = computeLCS(oldTokens, newTokens);
  const segments: InlineSegment[] = [];
  let oldIndex = 0;
  let newIndex = 0;
  for (const [oldMatch, newMatch] of matches) {
    if (oldIndex < oldMatch)
      segments.push({
        type: "removed",
        text: oldTokens.slice(oldIndex, oldMatch).join(""),
      });
    if (newIndex < newMatch)
      segments.push({
        type: "added",
        text: newTokens.slice(newIndex, newMatch).join(""),
      });
    segments.push({ type: "equal", text: oldTokens[oldMatch]! });
    oldIndex = oldMatch + 1;
    newIndex = newMatch + 1;
  }
  if (oldIndex < oldTokens.length)
    segments.push({
      type: "removed",
      text: oldTokens.slice(oldIndex).join(""),
    });
  if (newIndex < newTokens.length)
    segments.push({ type: "added", text: newTokens.slice(newIndex).join("") });
  return mergeSegments(segments);
}

/** Adds shared word-level highlights to adjacent removed/added lines. */
export function applyInlineHighlights(lines: DiffLine[]): void {
  for (let index = 0; index < lines.length - 1; index++) {
    const removed = lines[index]!;
    const added = lines[index + 1]!;
    if (removed.kind === "removed" && added.kind === "added") {
      const highlights = computeWordDiff(removed.text, added.text);
      if (highlights.length > 0) {
        removed.highlights = highlights;
        added.highlights = highlights;
      }
    }
  }
}

function tokenize(text: string): string[] {
  return text.match(/\s+|\w+|[^\s\w]/g) ?? [];
}

function computeLCS(a: string[], b: string[]): Array<[number, number]> {
  const table: number[][] = Array.from({ length: a.length + 1 }, () =>
    new Array(b.length + 1).fill(0),
  );
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      table[i]![j] =
        a[i - 1] === b[j - 1]
          ? table[i - 1]![j - 1]! + 1
          : Math.max(table[i - 1]![j]!, table[i]![j - 1]!);
    }
  }
  const matches: Array<[number, number]> = [];
  for (let i = a.length, j = b.length; i > 0 && j > 0;) {
    if (a[i - 1] === b[j - 1]) {
      matches.unshift([i - 1, j - 1]);
      i--;
      j--;
    } else if (table[i - 1]![j]! >= table[i]![j - 1]!) i--;
    else j--;
  }
  return matches;
}

function mergeSegments(segments: InlineSegment[]): InlineSegment[] {
  const merged: InlineSegment[] = [];
  for (const segment of segments) {
    const last = merged[merged.length - 1];
    if (last?.type === segment.type) last.text += segment.text;
    else if (segment.text) merged.push({ ...segment });
  }
  return merged;
}

/**
 * Diff-Renderer: Konvertiert strukturierte Diff-Daten in farbige ANSI-Ausgabe.
 * Unterstützt Compact- und Full-Modi.
 */
import type { Theme } from "@earendil-works/pi-coding-agent";
import { truncateToWidth } from "@earendil-works/pi-tui";
import { ellipsizeMiddle } from "../shared/paths.ts";
import type { DiffHunk, DiffStats, FileDiff } from "./types.ts";

/** Maximale Anzahl Hunk-Zeilen im Compact-Modus. */
const COMPACT_MAX_LINES = 6;

/** Breite des Zeilennummern-Feldes. */
const LINE_NUM_WIDTH = 5;

// ---------------------------------------------------------------------------
// Rendering-Funktionen
// ---------------------------------------------------------------------------

/**
 * Rendert den Compact-Modus: 1 Statistik-Zeile + wenige Hunk-Vorschauzeilen.
 */
export function renderCompact(
  diff: FileDiff,
  theme: Theme,
  width: number,
): string[] {
  const lines: string[] = [];
  const stats = diff.stats;

  // Statistik-Zeile
  lines.push(renderStatLine(stats, theme, width));

  // Erste Hunks (max COMPACT_MAX_LINES Zeilen)
  let rendered = 0;
  for (const hunk of diff.hunks) {
    if (rendered >= COMPACT_MAX_LINES) break;

    // Hunk-Header
    if (rendered > 0) lines.push(theme.fg("dim", "  …"));
    if (rendered >= COMPACT_MAX_LINES) break;

    const header = renderHunkHeader(hunk, theme);
    if (rendered + 1 <= COMPACT_MAX_LINES) {
      lines.push(truncate(header, width));
      rendered++;
    }

    // Hunk-Zeilen
    for (const dl of hunk.lines) {
      if (rendered >= COMPACT_MAX_LINES) break;
      lines.push(truncate(renderDiffLine(dl, theme, false), width));
      rendered++;
    }
  }

  if (
    rendered >= COMPACT_MAX_LINES &&
    totalDiffLines(diff) > COMPACT_MAX_LINES
  ) {
    const remaining = totalDiffLines(diff) - COMPACT_MAX_LINES;
    lines.push(theme.fg("dim", `  … ${remaining} weitere Zeilen`));
  }

  return lines;
}

/**
 * Rendert den Full-Modus: Vollständiger Diff mit Zeilennummern.
 */
export function renderFull(
  diff: FileDiff,
  theme: Theme,
  width: number,
): string[] {
  const lines: string[] = [];
  const stats = diff.stats;

  // Header
  lines.push(renderStatLine(stats, theme, width));

  for (const hunk of diff.hunks) {
    lines.push(truncate(renderHunkHeader(hunk, theme), width));
    for (const dl of hunk.lines) {
      lines.push(truncate(renderDiffLine(dl, theme, true), width));
    }
  }

  return lines;
}

/**
 * Rendert die Statistik-Zeile: "✎ path/to/file  +N −M  (K Hunks)"
 */
export function renderStatLine(
  stats: DiffStats,
  theme: Theme,
  width: number,
): string {
  const parts: string[] = [];
  const path = ellipsizeMiddle(stats.path, Math.max(1, width - 2));
  parts.push(theme.fg("accent", `✎ ${path}`));
  parts.push("  ");
  if (stats.linesAdded > 0) {
    parts.push(theme.fg("toolDiffAdded", `+${stats.linesAdded}`));
  }
  if (stats.linesAdded > 0 && stats.linesRemoved > 0) parts.push(" ");
  if (stats.linesRemoved > 0) {
    parts.push(theme.fg("toolDiffRemoved", `−${stats.linesRemoved}`));
  }
  if (stats.hunks > 1) {
    parts.push(theme.fg("dim", `  (${stats.hunks} Hunks)`));
  }
  return truncate(parts.join(""), width);
}

/**
 * Rendert den Hunk-Header: "@@ -oldStart,oldCount +newStart,newCount @@ heading"
 */
function renderHunkHeader(hunk: DiffHunk, theme: Theme): string {
  let header = theme.fg("accent", "@@");
  header += theme.fg("toolDiffRemoved", ` -${hunk.oldStart},${hunk.oldCount}`);
  header += theme.fg("toolDiffAdded", ` +${hunk.newStart},${hunk.newCount}`);
  header += theme.fg("accent", " @@");
  if (hunk.heading) {
    header += theme.fg("dim", ` ${hunk.heading}`);
  }
  return `  ${header}`;
}

/**
 * Rendert eine einzelne Diff-Zeile mit Farben und optionalen Zeilennummern.
 */
function renderDiffLine(
  dl: import("./types.ts").DiffLine,
  theme: Theme,
  showLineNums: boolean,
): string {
  let prefix = "";
  let content = "";
  let fg: (s: string) => string;
  let inlineStyled = false;

  switch (dl.kind) {
    case "added": {
      prefix = "+";
      fg = (s) => theme.fg("toolDiffAdded", s);
      content = renderInlineLine(dl.text, dl.highlights, "added", theme);
      inlineStyled = content !== dl.text;
      break;
    }
    case "removed": {
      prefix = "−";
      fg = (s) => theme.fg("toolDiffRemoved", s);
      content = renderInlineLine(dl.text, dl.highlights, "removed", theme);
      inlineStyled = content !== dl.text;
      break;
    }
    case "context": {
      prefix = " ";
      fg = (s) => theme.fg("toolDiffContext", s);
      content = dl.text;
      break;
    }
  }

  // Zeilennummern
  let numPart = "";
  if (showLineNums) {
    const oldNum =
      dl.oldLine !== undefined
        ? padNum(dl.oldLine)
        : " ".repeat(LINE_NUM_WIDTH);
    const newNum =
      dl.newLine !== undefined
        ? padNum(dl.newLine)
        : " ".repeat(LINE_NUM_WIDTH);
    numPart = theme.fg("dim", `${oldNum} ${newNum} `);
  }

  const prefixColor =
    dl.kind === "added"
      ? theme.fg("toolDiffAdded", prefix)
      : dl.kind === "removed"
        ? theme.fg("toolDiffRemoved", prefix)
        : theme.fg("dim", prefix);

  return `  ${prefixColor} ${numPart}${inlineStyled ? content : fg(content)}`;
}

/**
 * Rendert Zeileninhalt mit Inline-Highlights (Word-Level-Diff).
 */
function renderInlineLine(
  text: string,
  highlights: import("./types.ts").InlineSegment[] | undefined,
  lineKind: "added" | "removed",
  theme: Theme,
): string {
  if (!highlights || highlights.length === 0) return text;

  // Die gemeinsame Segmentliste enthält alten und neuen Text. Jede Diff-Zeile
  // zeigt nur ihre eigene Richtung; geänderte Wörter sind gelb hervorgehoben.
  let result = "";
  for (const segment of highlights) {
    if (segment.type === "equal") {
      result +=
        lineKind === "added"
          ? theme.fg("toolDiffAdded", segment.text)
          : theme.fg("toolDiffRemoved", segment.text);
    } else if (segment.type === lineKind) {
      result += theme.fg("warning", theme.bold(segment.text));
    }
  }
  return result || text;
}

// ---------------------------------------------------------------------------
// Hilfsfunktionen
// ---------------------------------------------------------------------------

function totalDiffLines(diff: FileDiff): number {
  let count = 0;
  for (const hunk of diff.hunks) {
    count++; // Hunk-Header
    count += hunk.lines.length;
  }
  return count;
}

function padNum(n: number): string {
  const s = String(n);
  return s.length >= LINE_NUM_WIDTH
    ? s
    : " ".repeat(LINE_NUM_WIDTH - s.length) + s;
}

function truncate(s: string, width: number): string {
  return truncateToWidth(s, Math.max(1, width), "…");
}

// Eigenständiger Test für dieses Fixture — unabhängig von tests/run.mjs,
// da diff-viewer/ bei diesem Benchmark-Referenzzustand nicht Teil des
// Haupt-Repos ist (siehe TASK.md).
import { existsSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Sucht "npm/node_modules/jiti" in den Elternverzeichnissen. Findet sowohl
// den Repo-Root (Original-Speicherort unter benchmarks/tasks/.../fixture/)
// als auch einen Benchmark-Worktree (dort liegt dieses Fixture direkt unter
// <worktree>/benchmark-fixture/, mit npm/node_modules als Symlink im
// Worktree selbst — siehe harness/reset-task.sh).
function findJitiEntry(startDir) {
  let dir = startDir;
  for (let i = 0; i < 10; i++) {
    const candidate = path.join(dir, "npm", "node_modules", "jiti");
    if (existsSync(candidate)) return candidate;
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  throw new Error("npm/node_modules/jiti not found above " + startDir);
}

const { createJiti } = require(findJitiEntry(__dirname));
const jiti = createJiti(__dirname);

const { computeLineDiff, scriptToHunks } = await jiti.import(
  path.join(__dirname, "diff-viewer/diff-algorithm.ts"),
);

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (condition) {
    passed += 1;
    return;
  }
  failed += 1;
  console.log("  FAIL: " + message);
}

// Bestehendes Verhalten (bleibt nach dem Fix unverändert):
// Änderungen mit echtem Abstand > 2*contextLines+1 bleiben getrennte Hunks.
{
  const before = Array.from({ length: 20 }, (_, i) => `line ${i}`).join("\n");
  const after = before
    .replace("line 2", "line two")
    .replace("line 17", "line seventeen");
  const script = computeLineDiff(before.split("\n"), after.split("\n"));
  const hunks = scriptToHunks(before.split("\n"), after.split("\n"), script);
  assert(hunks.length === 2, "distant changes stay in separate hunks");
}

// Regressionsfall für den injizierten Bug: zwei Änderungen mit exakt
// contextLines*2+1 = 7 Zeilen Abstand (contextLines Default = 3) müssen zu
// einem einzigen zusammenhängenden Hunk verschmelzen. Mit der kaputten
// Bedingung `<` statt `<=` werden sie fälschlich getrennt.
{
  const lines = Array.from({ length: 20 }, (_, i) => `line ${i}`);
  const before = lines.join("\n");
  const after = lines
    .map((l, i) => (i === 2 ? "line two" : i === 9 ? "line nine" : l))
    .join("\n");
  const script = computeLineDiff(before.split("\n"), after.split("\n"));
  const hunks = scriptToHunks(before.split("\n"), after.split("\n"), script);
  assert(
    hunks.length === 1,
    "changes exactly 2*contextLines+1 apart merge into one hunk (regression for the injected off-by-one)",
  );
}

console.log(
  "\n" +
    (failed === 0 ? "PASS" : "FAIL") +
    ": " +
    passed +
    " passed, " +
    failed +
    " failed",
);
if (failed > 0) process.exitCode = 1;

